function minCutCost(length, cuts) {
  const points = [0, ...[...cuts].sort((x, y) => x - y), length]
  const m = points.length
  const cost = Array.from({ length: m }, () => new Array(m).fill(0))
  for (let gap = 2; gap < m; gap++) {
    for (let i = 0; i + gap < m; i++) {
      const j = i + gap
      let best = Infinity
      for (let k = i + 1; k < j; k++) best = Math.min(best, cost[i][k] + cost[k][j])
      cost[i][j] = points[j] - points[i] + best
    }
  }
  return cost[0][m - 1]
}

