def min_cut_cost(length, cuts):
    points = [0] + sorted(cuts) + [length]
    m = len(points)
    cost = [[0] * m for _ in range(m)]
    for gap in range(2, m):
        for i in range(m - gap):
            j = i + gap
            row, best = cost[i], min(cost[i][k] + cost[k][j] for k in range(i + 1, j))
            row[j] = points[j] - points[i] + best
    return cost[0][m - 1]
